.inp-wrap { position: relative; width: 100%; max-width: 300px; }
.inp-outer { position: relative; border: 1px solid rgb(190, 197, 209); border-radius: 8px; padding: 14px; background: rgb(255, 255, 255); transition: border-color 0.15s; cursor: text; }
.inp-outer.focused { border-color: rgb(65, 71, 82); border-width: 1.5px; padding: 13.5px; }
.inp-outer.inp-error { border-color: rgb(197, 15, 31); }
.inp-outer.inp-success { border-color: rgb(48, 137, 86); }
.inp-outer.inp-disabled { background: rgb(247, 248, 250); cursor: not-allowed; border-color: rgb(221, 226, 235); }
.inp-float-label { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); font-size: 14px; color: rgb(134, 142, 158); transition: 0.15s; pointer-events: none; background: rgb(255, 255, 255); padding: 0px 2px; }
.inp-outer.focused .inp-float-label, .inp-outer.has-value .inp-float-label { top: 0px; font-size: 12px; color: rgb(65, 71, 82); }
.inp-outer.inp-error .inp-float-label { color: rgb(197, 15, 31); }
.inp-outer.inp-success .inp-float-label { color: rgb(48, 137, 86); }
.inp-outer.inp-disabled .inp-float-label { color: rgb(190, 197, 209); background: rgb(247, 248, 250); }
.inp-field { border: none; outline: none; font-size: 14px; font-weight: 400; color: rgb(24, 26, 31); font-family: inherit; background: transparent; padding: 0px; width: 100%; line-height: 1.4; }
.inp-field::placeholder { color: transparent; }
.inp-outer.focused .inp-field::placeholder { color: rgb(162, 169, 184); }
.inp-field:disabled { color: rgb(162, 169, 184); cursor: not-allowed; }
.inp-helper { font-size: 11px; margin-top: 4px; text-align: right; }
.inp-helper.error { color: rgb(197, 15, 31); }
.inp-helper.success { color: rgb(48, 137, 86); }
