.drp-select { width: 100%; padding: 14px 36px 14px 14px; border: none; border-radius: 8px; font-size: 14px; font-family: inherit; color: rgb(24, 26, 31); background: transparent; appearance: none; cursor: pointer; outline: none; }
.drp-select option { font-size: 14px; }
.drp-caret { position: absolute; right: 12px; top: 50%; transform: translateY(-50%); pointer-events: none; font-size: 12px; color: rgb(134, 142, 158); }
